//! OpenAPI spec for cron service.
//!
//! Generated by `utoipa` from `#[utoipa::path]` annotations on handlers.
//! The service exposes `GET /openapi.json` via `sentin8::openapi::openapi_route`
//! (OAPEC design §2: the spec covers every route the router serves; the
//! drift guard in `tests/` asserts both directions).
//!
//! The RFW POST-alias of schedule deletion (`POST /v1/schedules/{id}/delete`)
//! cannot reuse `handlers::delete_schedule` (one annotated handler = one
//! path in the spec), so the wrapper module below pins the alias path with
//! its own annotation and delegates to the same handler body.

use utoipa::OpenApi;

use crate::handlers;

/// Thin annotated POST-alias wrappers (Dash 28.14 - the RFW renderer is
/// POST-only): same handler body, alias path.
pub mod rfw_aliases {
    use crate::handlers;

    /// `POST /v1/schedules/{id}/delete` - RFW renderer alias of
    /// `DELETE /v1/schedules/{id}` (same operation, same gates).
    #[utoipa::path(
        post,
        path = "/v1/schedules/{id}/delete",
        params(("id" = uuid::Uuid, Path, description = "Schedule ID")),
        responses(
            (status = 204, description = "Schedule deleted (same contract as DELETE /v1/schedules/{id})"),
            (status = 403, description = "Missing cron:write scope"),
            (status = 404, description = "Schedule not found"),
        ),
        security(("sentin8:cron:write" = [])),
        tag = "cron",
    )]
    pub async fn delete_schedule_alias(
        axum::extract::State(state): axum::extract::State<handlers::AppState>,
        headers: axum::http::HeaderMap,
        q: axum::extract::Query<crate::handlers::TargetEnvQuery>,
        id: axum::extract::Path<uuid::Uuid>,
    ) -> Result<axum::http::StatusCode, (axum::http::StatusCode, String)> {
        handlers::delete_schedule(axum::extract::State(state), headers, q, id).await
    }
}

